/* Conjuros de Druida 2014; fuente PHB aportada por usuario. */
window.DMA_DRUID_SPELLS_1189=[{"n":"Druidcraft","l":0,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"30 feet","components":"V, S","duration":"Instantaneous","concentration":false,"description":"Whispering to the spirits of nature, you create one of the\nfollowing effects within range:\nYou create a tiny, harmless sensoryeffect that predicts\nwhat the weather will be at your location for the next\n24 hours. The effect might manifest as a golden orb\n\nfor clear skies, a cloud for rain, falling snowflakes for\nsnow, and so on. This effect persists for 1 round.\nYou instantly make a flower blossom, a seed pod open,\nor a leaf bud bloom.\n• You create an instantaneous, harmless sensory effect,\nsuch as falling leaves, a puff ofwind, the sound of a\nsmall animal, or the faint odor of skunk. The effect\nmust fit in a 5-foot cube.\n• You instantly light or snuff out a candle, a torch, or a\nsmall campfire.","fromHandbook":true},{"n":"Guidance","l":0,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Touch","components":"V, S","duration":"Concentration, up to 1 minute","concentration":true,"description":"You touch one willing creature. Once before the spell\nends, the target can roll a d4 and add the number rolled\nto one ability check of its choice. It can roll the die before\nor after making the ability check. The spell then ends.","fromHandbook":true},{"n":"Mending","l":0,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 minute","range":"Touch","components":"V, S, M (two lodestones)","duration":"Instantaneous","concentration":false,"description":"This spell repairs a single break or tear in an object\nyou touch, such as a broken chain link, two halves of\na broken key, a torn cloak, or a leaking wineskin. As\nlong as the break or tear is no larger than 1 foot in\nany dimension, you mend it, leaving no trace of the\nformer damage.\nThis spell can physically repair a magic item\nor construct, but the spell can't restore magic to\nsuch an object.","fromHandbook":true},{"n":"Poison Spray","l":0,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"10 feet","components":"V, S","duration":"Instantaneous","concentration":false,"description":"PART 1 �PELIs\nYou extend your hand toward a creature you can see\nwithin range and project a puff of noxious gas from your\npalm. The creature must succeed on a Constitution\nsaving throw or take ld12 poison damage.\nThis spell's damage increases by ld12 when you reach\n5th level (2dl2), 1 1th level (3d12), and 17th level (4dl2).","fromHandbook":true},{"n":"Produce Flame","l":0,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Self","components":"V, S","duration":"10 minutes","concentration":false,"description":"A flickering flame appears in your hand. The flame\nremains there for the duration and harms neitheryou\nnor your equipment. The flame sheds bright light in a\n10-foot radius and dim light for an additional 10 feet.\nThe spell ends ifyou dismiss it as an action or ifyou\ncast it again.\nYou can also attack with the flame, although doing so\nends the spell. When you cast this spell, or as an action\non a later turn, you can hurl the flame at a creature\nwithin 30 feet ofyou. Make a ranged spell attack. On a\nhit, the target takes ld8 fire damage.\nThis spell's damage increases by ld8 when you reach\n5th level (2d8), 1 lth level (3d8), and 17th level (4d8).","fromHandbook":true},{"n":"Resistance","l":0,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Touch","components":"V, S, M (a miniature cloak)","duration":"Concentration, up to 1 minute","concentration":true,"description":"You touch one willing creature. Once before the spell\nends, the target can roll a d4 and add the number\nrolled to one saving throw of its choice. It can roll\nthe die before or after making the saving throw. The\nspell then ends.","fromHandbook":true},{"n":"Shillelagh","l":0,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 bonus action","range":"Touch","components":"V, S, M (mistletoe, a shamrock leaf, and a","duration":"1 minute","concentration":false,"description":"The wood of a club or quarterstaffyou are holding is\nimbued with nature's power. For the duration, you can\nuse your spellcasting ability instead of Strength for\nthe attack and damage rolls of melee attacks using\nthat weapon, and the weapon's damage die becomes\na d8. The weapon also becomes magical, if it isn't\nalready. The spell ends ifyou cast it again or ifyou let go\nof the weapon.","fromHandbook":true},{"n":"Thorn Whip","l":0,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"30 feet","components":"V, S, M (the stem of a plant with thorns)","duration":"Instantaneous","concentration":false,"description":"You create a long, vine-like whip covered in thorns that\nlashes out at your command toward a creature in range.\nMake a melee spell attack against the target. If the\nattack hits, the creature takes ld6 piercing damage, and\nif the creature is Large or smaller, you pull the creature\nup to 10 feet closer to you.\nThis spell's damage increases by ld6 when you reach\n5th level (2d6), 1 1th level (3d6), and 17th level (4d6).","fromHandbook":true},{"n":"Animal Friendship","l":1,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"30 feet","components":"V, S, M (a morsel of food)","duration":"24 hours","concentration":false,"description":"This spell lets you convince a beast that you mean it no\nharm. Choose a beast that you can see within range.\nIt must see and hear you. If the beast's Intelligence is\n4 or higher, the spell fails. Otherwise, the beast must\nsucceed on a Wisdom saving throw or be charmed\nbyyou for the spell's duration. Ifyou or one ofyour\ncompanions harms the target, the spells ends.\nAt H\nigher Levels. When you cast this spell using\na spell slot of 2nd level or higher, you can affect one\nadditional beast for each slot level above 1st.","fromHandbook":true},{"n":"Charm Person","l":1,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"30 feet","components":"V, S","duration":"1 hour","concentration":false,"description":"You attempt to charm a humanoid you can see within\nrange. It must make a Wisdom saving throw, and does\nso with advantage ifyou or your companions are fighting\nit. If it fails the saving throw, it is charmed by you until\nthe spell ends or until you or your companions do\nanything harmful to it. The charmed creature regards\nyou as a friendly acquaintance. When the spell ends, the\ncreature knows it was charmed by you.\nAt Higher Levels. When you cast this spell using\na spell slot of 2nd level or higher, you can target one\nadditional creature for each slot level above 1st. The\ncreatures must be within 30 feet of each other when\nyou target them.\nCHILL TOUCH\nNecromancycantrip\nCasting Time: 1 action\nRange: 120 feet\nComponents: V, S\nDuration: 1 round\nYou create a ghostly, skeletal hand in the space of a\ncreature within range. Make a ranged spell attack\nagainst the creature to assail it with the chill of the\ngrave. On a hit, the target takes 1d8 necrotic damage,\nand it can't regain hit points until the start ofyour next\nturn. Until then, the hand clings to the target.\nIfyou hit an undead target, it also has disadvantage on\nattack rolls against you until the end ofyour next turn.\nThis spell's damage increases by 1d8 when you reach\n5th level (2d8), 1 1th level (3d8), and 17th level (4d8).","fromHandbook":true},{"n":"Create or Destroy Water","l":1,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"30 feet","components":"V, S, M (a drop ofwater if creating water","duration":"Instantaneous","concentration":false,"description":"You either create or destroy water.\nCreate W\nater. You create up to 10 gallons of clean\nwater within range in an open container. Alternatively,\nthe water falls as rain in a 30-foot cube within range,\nextinguishing exposed flames in the area.\nDestroy W\nater. You destroy up to 10 gallons ofwater\nin an open container within range. Alternatively, you\ndestroy fog in a 30-foot cube within range.\nAt Higher Levels. When you cast this spell using a\nspell slot of 2nd level or higher, you create or destroy\n10 additional gallons of water, or the size of the cube\nincreases by 5 feet, for each slot level above 1st.","fromHandbook":true},{"n":"Cure Wounds","l":1,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Touch","components":"V, S","duration":"Instantaneous","concentration":false,"description":"A creature you touch regains a number of hit points\nequal to ld8 + your spellcasting ability modifier. This\nspell has no effect on undead or constructs.\nAt Higher Levels. When you cast this spell using a\nspell slot of 2nd level or higher, the healing increases by\nld8 for each slot level above 1st.","fromHandbook":true},{"n":"Detect Magic","l":1,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Self","components":"V, S","duration":"Concentration, up to 10 minutes","concentration":true,"description":"For the duration, you sense the presence of magic\nwithin 30 feet ofyou. If you sense magic in this way, you\ncan use your action to see a faint aura around any visible\ncreature or object in the area that bears magic, and you\nlearn its school of magic, if any.\nThe spell can penetrate most barriers, but it is blocked\nby 1 foot of stone, 1 inch of common metal, a thin sheet\nof lead, or 3 feet of wood or dirt.","fromHandbook":true},{"n":"Detect Poison and Disease","l":1,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Self","components":"V, S, M (ayew leaf)","duration":"Concentration, up to 10 minutes","concentration":true,"description":"For the duration, you can sense the presence and\nlocation of poisons, poisonous creatures, and diseases\nwithin 30 feet ofyou. You also identify the kind of\npoison, poisonous creature, or disease in each case.\nThe spell can penetrate most barriers, but it is blocked\nby 1 foot of stone, 1 inch of common metal, a thin sheet\nof lead, or 3 feet ofwood or dirt.","fromHandbook":true},{"n":"Entangle","l":1,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"90 feet","components":"V, S","duration":"Concentration, up to 1 minute","concentration":true,"description":"Grasping weeds and vines sprout from the ground in a\n20-foot square starting from a point within range. For\nthe duration, these plants turn the ground in the area\ninto difficult terrain.\nA creature in the area when you cast the spell must\nsucceed on a Strength saving throw or be restrained\nby the entangling plants until the spell ends. A creature\nrestrained by the plants can use its action to make\na Strength check against your spell save DC. On a\nsuccess, it frees itself.\nWhen the spell ends, the conjured plants wilt away.","fromHandbook":true},{"n":"Faerie Fire","l":1,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"60 feet","components":"V","duration":"Concentration, up to 1 minute","concentration":true,"description":"Each object in a 20-foot cube within range is outlined in\nblue, green, or violet light (your choice). Any creature in\nthe area when the spell is cast is also outlined in light if\nit fails a Dexterity saving throw. For the duration, objects\nand affected creatures shed dim light in a 10-foot radius.\nAny attack roll against an affected creature or object\nhas advantage if the attacker can see it, and the affected\ncreature or object can't benefit from being invisible.","fromHandbook":true},{"n":"Fog Cloud","l":1,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"120 feet","components":"V, S","duration":"Concentration, up to 1 hour","concentration":true,"description":"You create a 20-foot-radius sphere of fog centered on a\npoint within range. The sphere spreads around corners,\nand its area is heavily obscured. It lasts for the duration\nor until a wind of moderate or greater speed (at least 10\nmiles per hour) disperses it.\nAt Higher Levels. When you cast this spell using a\nspell slot of 2nd level or higher, the radius of the fog\nincreases by 20 feet for each slot level above 1st.","fromHandbook":true},{"n":"Goodberry","l":1,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Touch","components":"V, S, M (a sprig of mistletoe)","duration":"Instantaneous","concentration":false,"description":"Up to ten berries appear in your hand and are infused\nwith magic for the duration. A creature can use its\naction to eat one berry. Eating a berry restores 1 hit\npoint, and the berry provides enough nourishment to\nsustain a creature for one day.\nThe berries lose their potency if they have not been\nconsumed within 24 hours of the casting of this spell.","fromHandbook":true},{"n":"Healing Word","l":1,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 bonus action","range":"60 feet","components":"V","duration":"Instantaneous","concentration":false,"description":"A creature ofyour choice that you can see within range\nregains hit points equal to 1d4 + your spellcasting\nability modifier. This spell has no effect on undead\nor constructs.\nAt H\nigherLevels. When you cast this spell using a\nspell slot of 2nd level or higher, the healing increases by\n1d4 for each slot level above 1st.","fromHandbook":true},{"n":"Jump","l":1,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Touch","components":"V, S, M (a grasshopper's hind leg)","duration":"1 minute","concentration":false,"description":"You touch a creature. The creature'sjump distance is\ntripled until the spell ends.","fromHandbook":true},{"n":"Longstrider","l":1,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Touch","components":"V, S, M (a pinch of dirt)","duration":"1 hour","concentration":false,"description":"You touch a creature. The target's speed increases by 10\nfeet until the spell ends.\n\nAt Higher Levels. When you cast this spell using\na spell slot of 2nd level or higher, you can target one\nadditional creature for each slot level above 1st.","fromHandbook":true},{"n":"Purify Food and Drink","l":1,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"10 feet","components":"V, S","duration":"Instantaneous","concentration":false,"description":"All nonmagical food and drink within a 5-foot-radius\nsphere centered on a point ofyour choice within range is\npurified and rendered free of poison and disease.","fromHandbook":true},{"n":"Speak with Animals","l":1,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Self","components":"V, S","duration":"10 minutes","concentration":false,"description":"You gain the ability to comprehend and verbally\ncommunicate with beasts for the duration. The\nknowledge and awareness of many beasts is limited\nby their intelligence, but at minimum, beasts can\ngive you information about nearby locations and\nmonsters, including whatever they can perceive or have\nperceived within the past day. You might be able to\npersuade a beast to perform a small favor foryou, at the\nDM's discretion.","fromHandbook":true},{"n":"Thunderwave","l":1,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Self (15-foot cube)","components":"V, S","duration":"Instantaneous","concentration":false,"description":"A wave of thunderous force sweeps out from you. Each\ncreature in a 15-foot cube originating from you must\nmake a Constitution saving throw. On a failed save, a\ncreature takes 2d8 thunder damage and is pushed 10\nfeet away from you. On a successful save, the creature\ntakes half as much damage and isn't pushed.\nIn addition, unsecured objects that are completely\nwithin the area ofeffect are automatically pushed 10 feet\naway from you by the spell's effect, and the spell emits a\nthunderous boom audible out to 300 feet.\nAt HigherLevels. When you cast this spell using a\nspell slot of 2nd level or higher, the damage increases by\nld8 for each slot level above 1st.","fromHandbook":true},{"n":"Animal Messenger","l":2,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"30 feet","components":"V, S, M (a morsel of food)","duration":"24 hours","concentration":false,"description":"By means of this spell, you use an animal to deliver a\nmessage. Choose a Tiny beast you can see within range,\nsuch as a squirrel, a blue jay, or a bat. You specify a\nlocation, which you must have visited, and a recipient\nwho matches a general description, such as \"a man or\nwoman dressed in the uniform of the town guard\" or \"a\nred-haired dwarf wearing a pointed hat.\" You also speak\na message of up to twenty-five words. The target beast\ntravels for the duration of the spell toward the specified\nP·\\Rl\" 3 SPILLS\nlocation, covering about 50 miles per 24 hours for a\nflying messenger, or 25 miles for other animals.\nWhen the messenger arrives, it delivers your message\nto the creature that you described, replicating the sound\nofyour voice. The messenger speaks only to a creature\nmatching the description you gave. If the messenger\ndoesn't reach its destination before the spell ends, the\nmessage is lost, and the beast makes its way back to\nwhere you cast this spell.\nAt Higher Levels. Ifyou cast this spell using a spell\nslot of 3nd level or higher, the duration of the spell\nincreases by 48 hours for each slot level above 2nd.","fromHandbook":true},{"n":"Barkskin","l":2,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Touch","components":"V, S, M (a handful of oak bark)","duration":"Concentration, up to 1 hour","concentration":true,"description":"You touch a willing creature. Until the spell ends, the\ntarget's skin has a rough, bark-like appearance, and the\ntarget's AC can't be less than 16, regardless ofwhat kind\nof armor it is wearing.","fromHandbook":true},{"n":"Beast Sense","l":2,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Touch","components":"S","duration":"Concentration, up to 1 hour","concentration":true,"description":"You touch a willing beast. For the duration of the spell,\nyou can use your action to see through the beast's eyes\nand hear what it hears, and continue to do so until\nyou use your action to return to your normal senses.\n\nWhile perceiving through the beast's senses, you gain\nthe benefits of any special senses possessed by that\ncreature, though you are blinded and deafened to your\nown surroundings.","fromHandbook":true},{"n":"Darkvision","l":2,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Touch","components":"V, S, M (either a pinch of dried","duration":"8 hours","concentration":false,"description":"You touch a willing creature to grant it the ability to\nsee in the dark. For the duration, that creature has\ndarkvision out to a range of 60 feet.","fromHandbook":true},{"n":"Enhance Ability","l":2,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Touch","components":"V, S, M (fur or a feather from a beast)","duration":"Concentration, up to 1 hour","concentration":true,"description":"You touch a creature and bestow upon it a magical\nenhancement. Choose one of the following effects; the\ntarget gains that effect until the spell ends.\nBear's Endurance. The target has advantage on\nConstitution checks. It also gains 2d6 temporary hit\npoints, which are lost when the spell ends.\nBull's Strength. The target has advantage\non Strength checks, and his or her carrying\ncapacity doubles.\nCat's Grace. The target has advantage on Dexterity\nchecks. It also doesn't take damage from falling 20 feet\nor less if it isn't incapacitated.\nEagle'\ns Splendor. The target has advantage on\nCharisma checks.\nFox'\ns Cunning. The target has advantage on\nIntelligence checks.\nOwl's Wisdom. The target has advantage on\nWisdom checks.\nAtHigher Levels. When you cast this spell using\na spell slot of 3rd level or higher, you can target one\nadditional creature for each slot level above 2nd.","fromHandbook":true},{"n":"Find Traps","l":2,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"120 feet","components":"V, S","duration":"Instantaneous","concentration":false,"description":"You sense the presence of any trap within range that\nis within line of sight. A trap, for the purpose of this\nspell, includes anything that would inflict a sudden or\nunexpected effect you consider harmful or undesirable,\nwhich was specifically intended as such by its creator.\nThus, the spell would sense an area affected by the\nalarm spell, a glyph ofwarding, or a mechanical pit trap,\nbut it would not reveal a natural weakness in the floor,\nan unstable ceiling, or a hidden sinkhole.\nThis spell merely reveals that a trap is present. You\ndon't learn the location of each trap, but you do learn the\ngeneral nature of the danger posed by a trap you sense.","fromHandbook":true},{"n":"Flame Blade","l":2,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 bonus action","range":"Self","components":"V, S, M (leaf ofsumac)","duration":"Concentration, up to 10 minutes","concentration":true,"description":"You evoke a fiery blade in your free hand. The blade is\nsimilar in size and shape to a scimitar, and it lasts for\nthe duration. If you let go of the blade, it disappears, but\nyou can evoke the blade again as a bonus action.\nYou can use your action to make a melee spell\nattack with the fiery blade. On a hit, the target takes\n3d6 fire damage.\nThe flaming blade sheds bright light in a 10-foot\nradius and dim light for an additional 10 feet.\nAt Higher Levels. When you cast this spell using a\nspell slot of 4th level or higher, the damage increases by\nld6 for every two slot levels above 2nd.","fromHandbook":true},{"n":"Flaming Sphere","l":2,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"60 feet","components":"V, S, M (a bit of tallow, a pinch of","duration":"Concentration, up to 1 minute","concentration":true,"description":"A 5-foot-diameter sphere of fire appears in an\nunoccupied space ofyourchoice within range and lasts\nfor the duration. Any creature that ends its turn within 5\nfeet of the sphere must make a Dexterity saving throw.\nThe creature takes 2d6 fire damage on a failed save, or\nhalf as much damage on a successful one.\nAs a bonus action, you can move the sphere up to 30\nfeet. Ifyou ram the sphere into a creature, that creature\nmust make the saving throw against the sphere's\ndamage, and the sphere stops moving this turn.\nWhen you move the sphere, you can direct it over\nbarriers up to 5 feet tall and jump it across pits up to\n10 feet wide. The sphere ignites flammable objects not\nbeing worn or carried, and it sheds bright light in a\n20-foot radius and dim light for an additional 20 feet.\n\nAt Higher Levels. When you cast this spell using a\nspell slot of 3rd level or higher, the damage increases by\nld6 for each slot level above 2nd.","fromHandbook":true},{"n":"Gust of Wind","l":2,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Self (60-foot line)","components":"V, S, M (a legume seed)","duration":"Concentration, up to 1 minute","concentration":true,"description":"A line ofstrong wind 60 feet long and 10 feet wide\nblasts from you in a direction you choose for the spell's\nduration. Each creature that starts its turn in the line\nmust succeed on a Strength saving throw or be pushed\n15 feet away from you in a direction following the line.\nAny creature in the line must spend 2 feet of\nmovement for every 1 foot it moves when moving\ncloser to you.\nThe gust disperses gas or vapor, and it extinguishes\ncandles, torches, and similar unprotected flames in\nthe area. It causes protected flames, such as those of\nlanterns, to dance wildly and has a 50 percent chance to\nextinguish them.\nAs a bonus action on each ofyour turns before the\nspell ends, you can change the direction in which the\nline blasts from you.","fromHandbook":true},{"n":"Heat Metal","l":2,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"60 feet","components":"V, S, M (a piece of iron and a flame)","duration":"Concentration, up to 1 minute","concentration":true,"description":"Choose a manufactured metal object, such as a metal\nweapon or a suit ofheavy or medium metal armor, that\nyou can see within range. You cause the object to glow\nred-hot. Any creature in physical contact with the object\ntakes 2d8 fire damage when you cast the spell. Until the\nspell ends, you can use a bonus action on each ofyour\nsubsequent turns to cause this damage again.\n\nIf a creature is holding or wearing the object and\ntakes the damage from it, the creature must succeed on\na Constitution saving throw or drop the object if it can. If\nit doesn't drop the object, it has disadvantage on attack\nrolls and ability checks until the start ofyour next turn.\nAt Higher Levels. When you cast this spell using a\nspell slot of 3rd level or higher, the damage increases by\n1d8 for each slot level above 2nd.","fromHandbook":true},{"n":"Hold Person","l":2,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"60 feet","components":"V, S, M (a small, straight piece of iron)","duration":"Concentration, up to 1 minute","concentration":true,"description":"Choose a humanoid that you can see within range.\nThe target must succeed on a Wisdom saving throw\nor be paralyzed for the duration. At the end of each of\nits turns, the target can make another Wisdom saving\nthrow. On a success, the spell ends on the target.\nAt HigherLevels. When you cast this spell using\na spell slot of 3rd level or higher, you can target one\nadditional humanoid for each slot level above 2nd. The\nhumanoids must be within 30 feet of each other when\nyou target them.","fromHandbook":true},{"n":"Lesser Restoration","l":2,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Touch","components":"V, S","duration":"Instantaneous","concentration":false,"description":"You touch a creature and can end either one disease or\none condition afflicting it. The condition can be blinded,\ndeafened, paralyzed, or poisoned.","fromHandbook":true},{"n":"Locate Animals or Plants","l":2,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Self","components":"V, S, M (a bit offur from a bloodhound)","duration":"Instantaneous","concentration":false,"description":"Describe or name a specific kind of beast or plant.\nConcentrating on the voice of nature in your\nsurroundings, you learn the direction and distance to\nthe closest creature or plant of that kind within 5 miles,\nifany are present.","fromHandbook":true},{"n":"Locate Object","l":2,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Self","components":"V, S, M (a forked twig)","duration":"Concentration, up to 10 minutes","concentration":true,"description":"Describe or name an object that is familiar to you. You\nsense the direction to the object's location, as long as\nthat object is within 1,000 feet of you. If the object is in\nmotion, you know the direction of its movement.\nThe spell can locate a specific object known to you,\nas long as you have seen it up close-within 30 feet-at\nleast once. Alternatively, the spell can locate the nearest\nobject of a particular kind, such as a certain kind of\napparel, jewelry, furniture, tool, or weapon.\nThis spell can't locate an object if any thickness of\nlead, even a thin sheet, blocks a direct path between you\nand the object.","fromHandbook":true},{"n":"Moonbeam","l":2,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"120 feet","components":"V, S, M (several seeds of any moonseed","duration":"Concentration, up to 1 minute","concentration":true,"description":"A silvery beam of pale light shines down in a 5-foot­\nradius, 40-foot-high cylinder centered on a point within\nrange. Until the spell ends, dim light fills the cylinder.\nWhen a creature enters the spell's area for the first\ntime on a turn or starts its turn there, it is engulfed\nin ghostly flames that cause searing pain, and it must\nmake a Constitution saving throw. It takes 2d10 radiant\ndamage on a failed save, or half as much damage on a\nsuccessful one.\nA shapechanger makes its saving throw with disad­\nvantage. If it fails, it also instantly reverts to its original\nform and can't assume a different form until it leaves the\nspell's light.\nOn your turns after you cast this spell, you can use an\naction to move the beam up to 60 feet in any direction.\nAt Higher Levels. When you cast this spell using a\nspell slot of 3rd level or higher, the damage increases by\nldlO for each slot level above 2nd.","fromHandbook":true},{"n":"Pass without Trace","l":2,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Self","components":"V, S, M (ashes from a burned leafof","duration":"Concentration, up to 1 hour","concentration":true,"description":"A veil ofshadows and silence radiates from you,\nmasking you and your companions from detection.\nFor the duration, each creature you choose within 30\nfeet ofyou (including you) has a +10 bonus to Dexterity\n\n(Stealth) checks and can't be tracked except by magical\nmeans. A creature that receives this bonus leaves\nbehind no tracks or other traces of its passage.","fromHandbook":true},{"n":"Protection from Poison","l":2,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Touch","components":"V, S","duration":"1 hour","concentration":false,"description":"You touch a creature. If it is poisoned, you neutralize the\npoison. If more than one poison afflicts the target, you\nneutralize one poison that you know is present, or you\nneutralize one at random.\nFor the duration, the target has advantage on saving\nthrows against being poisoned, and it has resistance to\npoison damage.","fromHandbook":true},{"n":"Spike Growth","l":2,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"150 feet","components":"V, S, M (seven sharp thorns or seven","duration":"Concentration, up to 10 minutes","concentration":true,"description":"The ground in a 20-foot radius centered on a point\nwithin range twists and sprouts hard spikes and thorns.\nThe area becomes difficult terrain for the duration.\nWhen a creature moves into or within the area, it takes\n2d4 piercing damage for every 5 feet it travels.\nThe transformation of the ground is camouflaged to\nlook natural. Any creature that can't see the area at the\ntime the spell is cast must make a Wisdom (Perception)\ncheck against your spell save DC to recognize the\nterrain as hazardous before entering it.","fromHandbook":true},{"n":"Call Lightning","l":3,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"120 feet","components":"V, S","duration":"Concentration, up to 10 minutes","concentration":true,"description":"A storm cloud appears in the shape of a cylinder that is\n10 feet tall with a 60-foot radius, centered on a point you\ncan see within range directly above you. The spell fails\nifyou can't see a point in the air where the storm cloud\ncould appear (for example, ifyou are in a room that can't\naccommodate the cloud).\nWhen you cast the spell, choose a point you can see\nunder the cloud. A bolt of lightning flashes down from\nthe cloud to that point. Each creature within 5 feet\nof that point must make a Dexterity saving throw. A\ncreature takes 3d10 lightning damage on a failed save,\nor half as much damage on a successful one. On each of\nyour turns until the spell ends, you can use your action\nto call down lightning in this way again, targeting the\nsame point or a different one.\nIfyou are outdoors in stormy conditions when you\ncast this spell, the spell gives you control over the\nexisting storm instead of creating a new one. Under\nsuch conditions, the spell's damage increases by ldlO.\nAt HigherLevels. When you cast this spell using a\nspell slot of 4th or higher level, the damage increases by\nldlO for each slot level above 3rd.","fromHandbook":true},{"n":"Conjure Animals","l":3,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"60 feet","components":"V, S","duration":"Concentration, up to 1 hour","concentration":true,"description":"You summon fey spirits that take the form of beasts and\nappear in unoccupied spaces that you can see within\nrange. Choose one of the following options for what\nappears:\n• One beast of challenge rating 2 or lower\n• Two beasts of challenge rating 1 or lower\n• Four beasts of challenge rating 1/2 or lower\n• Eight beasts of challenge rating 1/4 or lower\nEach beast is also considered fey, and it disappears\nwhen it drops to 0 hit points or when the spell ends.\nThe summoned creatures are friendly to you and your\ncompanions. Roll initiative for the summoned creatures\nas a group, which has its own turns. They obey any\nverbal commands that you issue to them (no action\nrequired by you). Ifyou don't issue any commands to\nthem, they defend themselves from hostile creatures,\nbut otherwise take no actions.\nThe DM has the creatures' statistics.\nAt HigherLevels. When you cast this spell using\ncertain higher-level spell slots, you choose one of the\nsummoning options above, and more creatures appear:\ntwice as many with a 5th-level slot, three times as many\nwith a 7th-level slot, and four times as many with a\n9th-level slot.","fromHandbook":true},{"n":"Daylight","l":3,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"60 feet","components":"V, S","duration":"1 hour","concentration":false,"description":"A 60-foot-radius sphere of light spreads out from a point\nyou choose within range. The sphere is bright light and\nsheds dim light for an additional 60 feet.\nIfyou chose a point on an object you are holding or\none that isn't being worn or carried, the light shines\nfrom the object and moves with it. Completely covering\nthe affected object with an opaque object, such as a bowl\nor a helm, blocks the light.\nIf any of this spell's area overlaps with an area of\ndarkness created by a spell of 3rd level or lower, the\nspell that created the darkness is dispelled.","fromHandbook":true},{"n":"Dispel Magic","l":3,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"120 feet","components":"V, S","duration":"Instantaneous","concentration":false,"description":"Choose one creature, object, or magical effect within\nrange. Any spell of 3rd level or lower on the target ends.\nFor each spell of 4th level or higher on the target, make\nan ability check using your spellcasting ability. The\nDC equals 10 + the spell's level. On a successful check,\nthe spell ends.\nAt Higher Levels. When you cast this spell using a\nspell slot of 4th level or higher, you automatically end\nthe effects of a spell on the target if the spell's level is\nequal to or less than the level of the spell slot you used.","fromHandbook":true},{"n":"Feign Death","l":3,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Touch","components":"V, S, M (a pinch of graveyard dirt)","duration":"1 hour","concentration":false,"description":"You touch a willing creature and put it into a cataleptic\nstate that is indistinguishable from death.\nFor the spell's duration, or until you use an action\nto touch the target and dismiss the spell, the target\nappears dead to all outward inspection and to spells\nused to determine the target's status. The target is\nblinded and incapacitated, and its speed drops to 0.\nThe target has resistance to all damage except psychic\ndamage. If the target is diseased or poisoned when you\ncast the spell, or becomes diseased or poisoned while\nunder the spell's effect, the disease and poison have no\neffect until the spell ends.","fromHandbook":true},{"n":"Meld into Stone","l":3,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Touch","components":"V, S","duration":"8 hours","concentration":false,"description":"You step into a stone object or surface large enough to\nfully contain your body, melding yourself and all the\nequipment you carry with the stone for the duration.\nUsing your movement, you step into the stone at a point\nyou can touch. Nothing ofyour presence remains visible\nor otherwise detectable by nonmagical senses.\nWhile merged with the stone, you can't see what\noccurs outside it, and any Wisdom (Perception) checks\nyou make to hear sounds outside it are made with\ndisadvantage. You remain aware of the passage of\ntime and can cast spells on yourself while merged in\nthe stone. You can use your movement to leave the\nstone where you entered it, which ends the spell. You\notherwise can't move.\nMinor physical damage to the stone doesn't harm\nyou, but its partial destruction or a change in its shape\n(to the extent that you no longer fit within it) expels you\nand deals 6d6 bludgeoning damage to you. The stone's\ncomplete destruction (or transmutation into a different\nsubstance) expels you and deals 50 bludgeoning damage\nto you. If expelled, you fall prone in an unoccupied space\nclosest to where you first entered.\nMELF's Acrn ARROW\n2nd-level evocation\nCasting Time: 1 action\nRange: 90 feet\nComponents: V, S, M (powdered rhubarb leaf and an\nadder's stomach)\nDuration: Instantaneous\nA shimmering green arrow streaks toward a target\nwithin range and bursts in a spray of acid. Make a\nranged spell attack against the target. On a hit, the\ntarget takes 4d4 acid damage immediately and 2d4 acid\ndamage at the end of its next turn. On a miss, the arrow\nsplashes the target with acid for half as much of the\ninitial damage and no damage at the end of its next turn.\nAt Higher Levels. Whenyou cast this spell using a\nspell slot of 3rd level or higher, the damage (both initial\nand later) increases by ld4 for each slot level above 2nd.","fromHandbook":true},{"n":"Plant Growth","l":3,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action or 8 hours","range":"150 feet","components":"V, S","duration":"Instantaneous","concentration":false,"description":"This spell channels vitality into plants within a specific\narea. There are two possible uses for the spell, granting\neither immediate or long-term benefits.\nIfyou cast this spell using 1 action, choose a point\nwithin range. All normal plants in a 100-foot radius\ncentered on that point become thick and overgrown. A\ncreature moving through the area must spend 4 feet of\nmovement for every 1 foot it moves.\nYou can exclude one or more areas of any size within\nthe spell's area from being affected.\nIfyou cast this spell over 8 hours, you enrich the\nland. All plants in a half-mile radius centered on a point\nwithin range become enriched for 1 year. The plants\nyield twice the normal amount offood when harvested.","fromHandbook":true},{"n":"Protection from Energy","l":3,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Touch","components":"V, S","duration":"Concentration, up to 1 hour","concentration":true,"description":"For the duration, the willing creature you touch has\nresistance to one damage type ofyour choice: acid, cold,\nfire, lightning, or thunder.","fromHandbook":true},{"n":"Sleet Storm","l":3,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"150 feet","components":"V, S, M (a pinch of dust and a few","duration":"Concentration, up to 1 minute","concentration":true,"description":"Until the spell ends, freezing rain and sleet fall in a\n20-foot-tall cylinder with a 40-foot radius centered on\na point you choose within range. The area is heavily\nobscured, and exposed flames in the area are doused.\nThe ground in the area is covered with slick ice,\nmaking it difficult terrain. When a creature enters the\nspell's area for the first time on a turn or starts its turn\nthere, it must make a Dexterity saving throw. On a failed\nsave, it falls prone.\nIf a creature starts its turn in the spell's area and\nis concentrating on a spell, the creature must make a\nsuccessful Constitution saving throw against your spell\nsave DC or lose concentration.","fromHandbook":true},{"n":"Speak with Plants","l":3,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Self (30-foot radius)","components":"V, S","duration":"10 minutes","concentration":false,"description":"You imbue plants within 30 feet ofyou with limited\nsentience and animation, giving them the ability\nto communicate with you and follow your simple\ncommands. You can question plants about events in the\nspell's area within the past day, gaining information\nabout creatures that have passed, weather, and other\ncircumstances.\nYou can also turn difficult terrain caused by plant\ngrowth (such as thickets and undergrowth) into ordinary\nterrain that lasts for the duration. Or you can turn\nordinary terrain where plants are present into difficult\nterrain that lasts for the duration, causing vines and\nbranches to hinder pursuers, for example.\nPlants might be able to perform other tasks on your\nbehalf, at the DM's discretion. The spell doesn't enable\nplants to uproot themselves and move about, but they\ncan freely move branches, tendrils, and stalks.\nIf a plant creature is in the area, you can communicate\nwith it as ifyou shared a common language, but you\ngain no magical ability to influence it.\nThis spell can cause the plants created by the entangle\nspell to release a restrained creature.","fromHandbook":true},{"n":"Water Breathing","l":3,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"30 feet","components":"V, S, M (a short reed or piece of straw)","duration":"24 hours","concentration":false,"description":"This spell grants up to ten willing creatures you can see\nwithin range the ability to breathe underwater until the\nspell ends. Affected creatures also retain their normal\nmode of respiration.","fromHandbook":true},{"n":"Water Walk","l":3,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"30 feet","components":"V, S, M (a piece of cork)","duration":"1 hour","concentration":false,"description":"This spell grants the ability to move across any liquid\nsurface-such as water, acid, mud, snow, quicksand,\nor lava-as if it were harmless solid ground (creatures\ncrossing molten lava can still take damage from the\nheat). Up to ten willing creatures you can see within\nrange gain this ability for the duration.\nIfyou target a creature submerged in a liquid, the\nspell carries the target to the surface of the liquid at a\nrate of 60 feet per round.","fromHandbook":true},{"n":"Wind Wall","l":3,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"120 feet","components":"V, S, M (a tiny fan and a feather of","duration":"Concentration, up to 1 minute","concentration":true,"description":"A wall of strong wind rises from the ground at a point\nyou choose within range. You can make the wall up\nto 50 feet long, 15 feet high, and 1 foot thick. You can\nshape the wall in anywayyou choose so long as it\nmakes one continuous path along the ground. The wall\nlasts for the duration.\nWhen the wall appears, each creature within its area\nmust make a Strength saving throw. A creature takes\n3d8 bludgeoning damage on a failed save, or half as\nmuch damage on a successful one.\nThe strong wind keeps fog, smoke, and other gases at\nbay. Small or smaller flying creatures or objects can't\npass through the wall. Loose, lightweight materials\nbrought into the wall fly upward. Arrows, bolts, and\nother ordinary projectiles launched at targets behind\nthe wall are deflected upward and automatically miss.\n(Boulders hurled bygiants or siege engines, and similar\nprojectiles, are unaffected.) Creatures in gaseous form\ncan't pass through it.","fromHandbook":true},{"n":"Blight","l":4,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"30 feet","components":"V, S","duration":"Instantaneous","concentration":false,"description":"Necromantic energywashes over a creature ofyour\nchoice that you can see within range, draining moisture\nand vitality from it. The target must make a Constitution\nsaving throw. The target takes 8d8 necrotic damage on\na failed save, or half as much damage on a successful\none. This spell has no effect on undead or constructs.\nIfyou target a plant creature or a magical plant, it\nmakes the saving throw with disadvantage, and the spell\ndeals maximum damage to it.\nIfyou target a nonmagical plant that isn't a creature,\nsuch as a tree or shrub, it doesn't make a saving throw;\nit simply withers and dies.\nAt Higher Levels. When you cast this spell using a\nspell slot of 5th level or higher, the damage increases by\nld8 for each slot level above 4th.","fromHandbook":true},{"n":"Confusion","l":4,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"90 feet","components":"V, S, M (three nut shells)","duration":"Concentration, up to 1 minute","concentration":true,"description":"This spell assaults and twists creatures' minds,\nspawning delusions and provoking uncontrolled action.\nEach creature in a 10-foot-radius sphere centered on\na point you choose within range must succeed on a\nWisdom saving throw when you cast this spell or be\naffected by it.\nAn affected target can't take reactions and must roll\na dlO at the start of each of its turns to determine its\nbehavior for that turn.\n\ndlO Behavior\nThe creature uses all its movement to move in a\nrandom direction. To determine the direction, roll\na d8 and assign a direction to each die face. The\ncreature doesn't take an action this turn.\n2-6 The creature doesn't move or take actions this turn.\n7-8 The creature uses its action to make a melee attack\nagainst a randomly determined creature within its\nreach. Ifthere is no creature within its reach, the\ncreature does nothing this turn.\n9-10 The creature can act and move normally.\nAt the end ofeach of its turns, an affected target can\nmake a Wisdom saving throw. If it succeeds, this effect\nends for that target.\nAt HigherLevels. When you cast this spell using a\nspell slot of 5th level or higher, the radius of the sphere\nincreases by 5 feet for each slot level above 4th.","fromHandbook":true},{"n":"Conjure Minor Elementals","l":4,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 minute","range":"90 feet","components":"V, S","duration":"Concentration, up to 1 hour","concentration":true,"description":"You summon elementals that appear in unoccupied\nspaces that you can see within range. You choose one\nthe following options for what appears:\n• One elemental of challenge rating 2 or lower\nTwo elementals of challenge rating 1 or lower\n• Four elementals of challenge rating 1/2 or lower\n• Eight elementals of challenge rating 1/4 or lower.\nAn elemental summoned by this spell disappears when\nit drops to 0 hit points or when the spell ends.\nThe summoned creatures are friendly to you and your\ncompanions. Roll initiative for the summoned creatures\nas a group, which has its own turns. They obey any\nverbal commands that you issue to them (no action\nrequired by you). If you don't issue any commands to\nthem, they defend themselves from hostile creatures,\nbut otherwise take no actions.\nThe DM has the creatures' statistics.\nAt Higher Levels. When you cast this spell using\ncertain higher-level spell slots, you choose one of the\nsummoning options above, and more creatures appear:\ntwice as many with a 6th-level slot and three times as\nmany with an 8th-level slot.","fromHandbook":true},{"n":"Conjure Woodland Beings","l":4,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"60 feet","components":"V, S, M (one holly berry per","duration":"Concentration, up to 1 hour","concentration":true,"description":"You summon fey creatures that appear in unoccupied\nspaces that you can see within range. Choose one of the\nfollowing options for what appears:\n• One fey creature of challenge rating 2 or lower\nTwo fey creatures of challenge rating 1 or lower\n• Four fey creatures of challenge rating 1/2 or lower\n• Eight fey creatures of challenge rating 1/4 or lower\nA summoned creature disappears when it drops to 0 hit\npoints or when the spell ends.\nThe summoned creatures are friendly to you and your\ncompanions. Roll initiative for the summoned creatures\nas a group, which have their own turns. They obey any\nverbal commands that you issue to them (no action\nrequired by you). Ifyou don't issue any commands to\nthem, they defend themselves from hostile creatures,\nbut otherwise take no actions.\nThe DM has the creatures' statistics.\nAt HigherLevels. When you cast this spell using\ncertain higher-level spell slots, you choose one of the\nsummoning options above, and more creatures appear:\ntwice as many with a 6th-level slot and three times as\nmany with an 8th-level slot.","fromHandbook":true},{"n":"Control Water","l":4,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"300 feet","components":"V, S, M (a drop ofwater and a","duration":"Concentration, up to 10 minutes","concentration":true,"description":"Until the spell ends, you control any freestanding water\ninside an area you choose that is a cube up to 100 feet\non a side. You can choose from any of the following\neffects when you cast this spell. As an action on your\nturn, you can repeat the same effect or choose a\ndifferent one.\nFlood. You cause the water level of all standing water in\nthe area to rise by as much as 20 feet. Ifthe area includes\na shore, the flooding water spills over onto dry land.\nIfyou choose an area in a large body of water, you\ninstead create a 20-foot tall wave that travels from one\nside of the area to the other and then crashes down. Any\nHuge or smaller vehicles in the wave's path are carried\nwith it to the other side. Any Huge or smaller vehicles\nstruck by the wave have a 25 percent chance of capsizing.\nThe water level remains elevated until the spell ends\nor you choose a different effect. If this effect produced\nPJ\\R1 3 SPELLS\n\na wave, the wave repeats on the start ofyour next turn\nwhile the flood effect lasts.\nPart W\nater. You cause water in the area to move\napart and create a trench. The trench extends across\nthe spell's area, and the separated water forms a wall to\neither side. The trench remains until the spell ends or\nyou choose a different effect. The water then slowly fills\nin the trench over the course of the next round until the\nnormal water level is restored.\nRedirect Flow. You cause flowing water in the area\nto move in a direction you choose, even if the water has\nto flow over obstacles, up walls, or in other unlikely\ndirections. The water in the area moves as you direct\nit, but once it moves beyond the spell's area, it resumes\nits flow based on the terrain conditions. The water\ncontinues to move in the direction you chose until the\nspell ends or you choose a different effect.\nWhirlpool. This effect requires a body of water\nat least 50 feet square and 25 feet deep. You cause\na whirlpool to form in the center of the area. The\nwhirlpool forms a vortex that is 5 feet wide at the\nbase, up to 50 feet wide at the top, and 25 feet tall. Any\ncreature or object in the water and within 25 feet of the\nvortex is pulled 10 feet toward it. A creature can swim\naway from the vortex by making a Strength (Athletics)\ncheck against your spell save DC.\nWhen a creature enters the vortex for the first time on\na turn or starts its turn there, it must make a Strength\nsaving throw. On a failed save, the creature takes 2d8\nbludgeoning damage and is caught in the vortex until\nthe spell ends. On a successful save, the creature takes\nhalf damage, and isn't caught in the vortex. A creature\ncaught in the vortex can use its action to try to swim\naway from the vortex as described above, but has\ndisadvantage on the Strength (Athletics) check to do so.\nThe first time each turn that an object enters the\nvortex, the object takes 2d8 bludgeoning damage; this\ndamage occurs each round it remains in the vortex.","fromHandbook":true},{"n":"Dominate Beast","l":4,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"60 feet","components":"V, S","duration":"Concentration, up to 1 minute","concentration":true,"description":"You attempt to beguile a beast that you can see within\nrange. It must succeed on a Wisdom saving throw or be\ncharmed byyou for the duration. Ifyou or creatures that\nare friendly to you are fighting it, it has advantage on the\nsaving throw.\nWhile the beast is charmed, you have a telepathic link\nwith it as long as the two ofyou are on the same plane\nofexistence. You can use this telepathic link to issue\ncommands to the creature while you are conscious (no\naction required), which it does its best to obey. You can\nspecify a simple and general course of action, such as\n\"Attack that creature,\" \"Run over there,\" or \"Fetch that\nobject.\" If the creature completes the order and doesn't\nreceive further direction from you, it defends and\npreserves itselfto the best of its ability.\nYou can use your action to take total and precise\ncontrol of the target. Until the end ofyour next turn, the\ncreature takes only the actions you choose, and doesn't\ndo anything that you don't allow it to do. During this\ntime, you can also cause the creature to use a reaction,\nbut this requires you to use your own reaction as well.\nEach time the target takes damage, it makes a new\nWisdom saving throwagainst the spell. If the saving\nthrow succeeds, the spell ends.\nAt HigherLevels. When you cast this spell with a\n5th-level spell slot, the duration is concentration, up\nto 10 minutes. When you use a 6th-level spell slot,\nthe duration is concentration, up to 1 hour. When you\nuse a spell slot of 7th level or higher, the duration is\nconcentration, up to 8 hours.","fromHandbook":true},{"n":"Freedom of Movement","l":4,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Touch","components":"V, S, M (a leather strap, bound around the","duration":"1 hour","concentration":false,"description":"You touch a willing creature. For the duration, the\ntarget's movement is unaffected by difficult terrain, and\nspells and other magical effects can neither reduce\nthe target's speed nor cause the target to be paralyzed\nor restrained.\nThe target can also spend 5 feet of movement to\nautomatically escape from nonmagical restraints, such\nas manacles or a creature that has it grappled. Finally,\nbeing underwater imposes no penalties on the target's\nmovement or attacks.","fromHandbook":true},{"n":"Giant Insect","l":4,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"30 feet","components":"V, S","duration":"Concentration, up to 10 minutes","concentration":true,"description":"You transform up to ten centipedes, three spiders, five\nwasps, or one scorpion within range into giant versions\nof their natural forms for the duration. A centipede\nbecomes a giant centipede, a spider becomes a giant\nspider, a wasp becomes a giant wasp, and a scorpion\nbecomes a giant scorpion.\nEach creature obeys your verbal commands, and\nin combat, they act on your turn each round. The DM\nhas the statistics for these creatures and resolves their\nactions and movement.\nA creature remains in its giant size for the duration,\nuntil it drops to 0 hit points, or until you use an action to\ndismiss the effect on it.\nThe DM might allow you to choose different targets.\nFor example, ifyou transform a bee, its giant version\nmight have the same statistics as a giant wasp.","fromHandbook":true},{"n":"Grasping Vine","l":4,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 bonus action","range":"30 feet","components":"V, S","duration":"Concentration, up to 1 minute","concentration":true,"description":"You conjure a vine that sprouts from the ground in an\nunoccupied space ofyour choice that you can see within\nrange. When you cast this spell, you can direct the vine\nto lash out at a creature within 30 feet of it that you can\nsee. That creature must succeed on a Dexterity saving\nthrow or be pulled 20 feet directly toward the vine.\nUntil the spell ends, you can direct the vine to lash out\nat the same creature or another one as a bonus action\non each ofyour turns.","fromHandbook":true},{"n":"Hallucinatory Terrain","l":4,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"10 minutes","range":"300 feet","components":"V, S, M (a stone, a twig, and a bit","duration":"24 hours","concentration":false,"description":"You make natural terrain in a 150-foot cube in range\nlook, sound, and smell like some other sort of natural\nterrain. Thus, open fields or a road can be made to\nresemble a swamp, hill, crevasse, or some other difficult\nor impassable terrain. A pond can be made to seem\nlike a grassy meadow, a precipice like a gentle slope,\nor a rock-strewn gully like a wide and smooth road.\nManufactured structures, equipment, and creatures\nwithin the area aren't changed in appearance.\nThe tactile characteristics of the terrain are\nunchanged, so creatures entering the area are likely to\nsee through the illusion. If the difference isn't obvious\nby touch, a creature carefully examining the illusion can\nattempt an Intelligence (Investigation) check against\nyour spell save DC to disbelieve it. A creature who\ndiscerns the illusion for what it is, sees it as a vague\nimage superimposed on the terrain.","fromHandbook":true},{"n":"Ice Storm","l":4,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"300 feet","components":"V, S, M (a pinch of dust and a few","duration":"Instantaneous","concentration":false,"description":"A hail of rock-hard ice pounds to the ground in a\n20-foot-radius, 40-foot-high cylinder centered on a\npoint within range. Each creature in the cylinder must\nmake a Dexterity saving throw. A creature takes 2d8\nbludgeoning damage and 4d6 cold damage on a failed\nsave, or half as much damage on a successful one.\nHailstones turn the storm's area of effect into difficult\nterrain until the end ofyour next turn.\nAt Higher Levels. When you cast this spell using a\nspell slot of 5th level or higher, the bludgeoning damage\nincreases by ld8 for each slot level above 4th.","fromHandbook":true},{"n":"Locate Creature","l":4,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Self","components":"V, S, M (a bit offur from a bloodhound)","duration":"Concentration, up to 1 hour","concentration":true,"description":"Describe or name a creature that is familiar to you. You\nsense the direction to the creature's location, as long as\nthat creature is within 1,000 feet of you. If the creature\nis moving, you know the direction of its movement.\nThe spell can locate a specific creature known to\nyou, or the nearest creature of a specific kind (such as\na human or a unicorn), so long as you have seen such a\ncreature up close-within 30 feet-at least once. If the\ncreature you described or named is in a different form,\nsuch as being under the effects of a polymorph spell,\nthis spell doesn't locate the creature.\nThis spell can't locate a creature if running water at\nleast 10 feet wide blocks a direct path between you and\nthe creature.","fromHandbook":true},{"n":"Polymorph","l":4,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"60 feet","components":"V, S, M (a caterpillar cocoon)","duration":"Concentration, up to 1 hour","concentration":true,"description":"This spell transforms a creature thatyou can see within\nrange into a new form. An unwilling creature must\nmake a Wisdom saving throw to avoid the effect. The\nspell has no effect on a shapechanger or a creature with\n0 hit points.\nThe transformation lasts for the duration, or until\nthe target drops to 0 hit points or dies. The new form\ncan be any beast whose challenge rating is equal to or\nless than the target's (or the target's level, if it doesn't\nhave a challenge rating). The target's game statistics,\nincluding mental ability scores, are replaced by the\nstatistics of the chosen beast. It retains its alignment\nand personality.\nThe target assumes the hit points of its new form.\nWhen it reverts to its normal form, the creature\nreturns to the number of hit points it had before it\ntransformed. If it reverts as a result of dropping to\n0 hit points, any excess damage carries over to its\nnormal form. As long as the excess damage doesn't\nreduce the creature's normal form to 0 hit points, it isn't\nknocked unconscious.\nThe creature is limited in the actions it can perform by\nthe nature of its new form, and it can't speak, cast spells,\nor take any other action that requires hands or speech.\nThe target's gear melds into the new form. The\ncreature can't activate, use, wield, or otherwise benefit\nfrom any of its equipment.","fromHandbook":true},{"n":"Stone Shape","l":4,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Touch","components":"V, S, M (soft clay, which must be worked","duration":"Instantaneous","concentration":false,"description":"You touch a stone object of Medium size or smaller or\na section of stone no more than 5 feet in any dimension\nand form it into any shape that suits your purpose. So,\nfor example, you could shape a large rock into a weapon,\nidol, or coffer, or make a small passage through a wall,\nas long as the wall is less than 5 feet thick. You could\nalso shape a stone door or its frame to seal the door\nshut. The object you create can have up to two hinges\nand a latch, but finer mechanical detail isn't possible.","fromHandbook":true},{"n":"Stoneskin","l":4,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Touch","components":"V, S, M (diamond dust worth 100 gp,","duration":"Concentration, up to 1 hour","concentration":true,"description":"This spell turns the flesh of a willing creature you touch\nas hard as stone. Until the spell ends, the target has\nresistance to nonmagical bludgeoning, piercing, and\nslashing damage.","fromHandbook":true},{"n":"Wall of Fire","l":4,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"120 feet","components":"V, S, M (a small piece of phosphorus)","duration":"Concentration, up to 1 minute","concentration":true,"description":"You create a wall of fire on a solid surface within\nrange. You can make the wall up to 60 feet long, 20\nfeet high, and 1 foot thick, or a ringed wall up to 20 feet\nin diameter, 20 feet high, and 1 foot thick. The wall is\nopaque and lasts for the duration.\nWhen the wall appears, each creature within its area\nmust make a Dexterity saving throw. On a failed save, a\ncreature takes 5d8 fire damage, or half as much damage\non a successful save.\nOne side of the wall, selected by you when you cast\nthis spell, deals 5d8 fire damage to each creature that\nends its turn within 10 feet of that side or inside the\nwall. A creature takes the same damage when it enters\nthe wall for the first time on a turn or ends its turn there.\nThe other side of the wall deals no damage.\nAt Higher Levels. When you cast this spell using a\nspell slot of 5th level or higher, the damage increases by\nld8 for each slot level above 4th.","fromHandbook":true},{"n":"Antilife Shell","l":5,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Self (10-foot radius)","components":"V, S","duration":"Concentration, up to 1 hour","concentration":true,"description":"A shimmering barrier extends out from you in a 10-foot\nradius and moves with you, remaining centered on\nyou and hedging out creatures other than undead and\nconstructs. The barrier lasts for the duration.\nThe barrier prevents an affected creature from\npassing or reaching through. An affected creature\ncan cast spells or make attacks with ranged or reach\nweapons through the barrier.\nIf you move so that an affected creature is forced to\npass through the barrier, the spell ends.","fromHandbook":true},{"n":"Awaken","l":5,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"8 hours","range":"Touch","components":"V, S, M (an agate worth at least 1,000 gp,","duration":"Instantaneous","concentration":false,"description":"After spending the casting time tracing magical\npathways within a precious gemstone, you touch a Huge\nor smaller beast or plant. The target must have either\nno Intelligence score or an Intelligence of 3 or less. The\ntarget gains an Intelligence of 10. The target also gains\nthe ability to speak one language you know. If the target\nis a plant, it gains the ability to move its limbs, roots,\nvines, creepers, and so forth, and it gains senses similar\nto a human's. Your DM chooses statistics appropriate\nfor the awakened plant, such as the statistics for the\nawakened shrub or the awakened tree.\nThe awakened beast or plant is charmed by you for\n30 days or until you or your companions do anything\nharmful to it. When the charmed condition ends,\nthe awakened creature chooses whether to remain\nfriendly to you, based on how you treated it while\nit was charmed.","fromHandbook":true},{"n":"Commune with Nature","l":5,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 minute","range":"Self","components":"V, S","duration":"Instantaneous","concentration":false,"description":"You briefly become one with nature and gain knowledge\nof the surrounding territory. In the outdoors, the spell\ngivesyou knowledge of the land within 3 miles ofyou.\nIn caves and other natural underground settings, the\nradius is limited to 300 feet. The spell doesn't function\nwhere nature has been replaced by construction, such\nas in dungeons and towns.\nYou instantly gain knowledge of up to three facts of\nyour choice about any of the following subjects as they\nrelate to the area:\n• terrain and bodies ofwater\n• prevalent plants, minerals, animals, or peoples\npowerful celestials, fey, fiends, elementals, or undead\n• influence from other planes of existence\n• buildings\nFor example, you could determine the location of\npowerful undead in the area, the location of major\nsources ofsafe drinking water, and the location of any\nnearby towns.","fromHandbook":true},{"n":"Conjure Elemental","l":5,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 minute","range":"90 feet","components":"V, S, M (burning incense for air, soft clay","duration":"Concentration, up to 1 hour","concentration":true,"description":"You call forth an elemental servant. Choose an area ofair,\nearth, fire, or water that fills a 10-foot cube within range.\nAn elemental of challenge rating 5 or lower appropriate\nto the area you chose appears in an unoccupied space\nwithin 10 feet of it. For example, a fire elemental\nemerges from a bonfire, and an earth elemental rises\nup from the ground. The elemental disappears when it\ndrops to 0 hit points or when the spell ends.\nThe elemental is friendly to you and your companions\nfor the duration. Roll initiative for the elemental, which\nhas its own turns. It obeys anyverbal commands that\nyou issue to it (no action required byyou). Ifyou don't\nissue any commands to the elemental, it defends itself\nfrom hostile creatures but otherwise takes no actions.\nIfyour concentration is broken, the elemental doesn't\ndisappear. Instead, you lose control of the elemental,\nit becomes hostile toward you and your companions,\nand it might attack. An uncontrolled elemental can't\nbe dismissed by you, and it disappears 1 hour after\nyou summoned it.\nThe DM has the elemental's statistics.\nAt HigherLevels. When you cast this spell using\na spell slot of 6th level or higher, the challenge rating\nincreases by 1 for each slot level above 5th.","fromHandbook":true},{"n":"Contagion","l":5,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Touch","components":"","duration":"7 days","concentration":false,"description":"Your touch inflicts disease. Make a melee spell attack\nagainst a creature within your reach. On a hit, the\ntarget is poisoned.\nAt the end of each of the poisoned target's turns, the\ntarget must make a Constitution saving throw. If the\ntarget succeeds on three of these saves, it is no longer\npoisoned, and the spell ends. If the target fails three of\nthese saves, the target is no longer poisoned, but choose\none of the diseases below. The target is subjected to the\nchosen disease for the spell's duration.\nSince this spell induces a natural disease in its\ntarget, any effect that removes a disease or otherwise\nameliorates a disease's effects apply to it.\nBlinding Sickness. Pain grips the creature's mind,\nand its eyes turn milky white. The creature has\ndisadvantage on Wisdom checks and Wisdom saving\nthrows and is blinded.\nFilth Fever. A raging fever sweeps through the\ncreature's body. The creature has disadvantage on\nStrength checks, Strength saving throws, and attack\nrolls that use Strength.\nFlesh Rot. The creature's flesh decays. The creature\nhas disadvantage on Charisma checks and vulnerability\nto all damage.\nMind/ire. The creature's mind becomes feverish. The\ncreature has disadvantage on Intelligence checks and\nIntelligence saving throws, and the creature behaves as\nif under the effects of the confusion spell during combat.\nSeizure. The creature is overcome with shaking.\nThe creature has disadvantage on Dexterity checks,\nDexterity saving throws, and attack rolls that\nuse Dexterity.\nSlimy Doom. The creature begins to bleed\nuncontrollably. The creature has disadvantage on\nConstitution checks and Constitution saving throws.\nIn addition, whenever the creature takes damage, it is\nstunned until the end of its next turn.","fromHandbook":true},{"n":"Geas","l":5,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 minute","range":"60 feet","components":"V","duration":"30 days","concentration":false,"description":"You place a magical command on a creature that you\ncan see within range, forcing it to carry out some\n\nservice or refrain from some action or course of activity\nas you decide. If the creature can understand you, it\nmust succeed on a Wisdom saving throw or become\ncharmed by you for the duration. While the creature\nis charmed by you, it takes SdlO psychic damage\neach time it acts in a manner directly counter to your\ninstructions, but no more than once each day. A creature\nthat can't understand you is unaffected by the spell.\nYou can issue any command you choose, short of an\nactivity that would result in certain death. Should you\nissue a suicidal command, the spell ends.\nYou can end the spell early by using an action to\ndismiss it. A remove curse, greaterrestoration, or wish\nspell also ends it.\nAt HigherLevels. When you cast this spell using\na spell slot of 7th or 8th level, the duration is 1 year.\nWhen you cast this spell using a spell slot of 9th level,\nthe spell lasts until it is ended by one of the spells\nmentioned above.","fromHandbook":true},{"n":"Greater Restoration","l":5,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Touch","components":"V, S, M (diamond dust worth at least 100","duration":"Instantaneous","concentration":false,"description":"You imbue a creature you touch with positive energy to\nundo a debilitating effect. You can reduce the target's\nexhaustion level by one, or end one of the following\neffects on the target:\nOne effect that charmed or petrified the target\n• One curse, including the target's attunement to a\ncursed magic item\nAny reduction to one of the target's ability scores\nOne effect reducing the target's hit point maximum","fromHandbook":true},{"n":"Insect Plague","l":5,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"300 feet","components":"V, S, M (a few grains of sugar, some","duration":"Concentration, up to 10 minutes","concentration":true,"description":"Swarming, biting locusts fill a 20-foot-radius sphere\ncentered on a point you choose within range. The sphere\nspreads around corners. The sphere remains for the\nduration, and its area is lightly obscured. The sphere's\narea is difficult terrain.\nWhen the area appears, each creature in it must\nmake a Constitution saving throw. A creature takes\n4d10 piercing damage on a failed save, or half as much\ndamage on a successful one. A creature must also make\nthis saving throw when it enters the spell's area for the\nfirst time on a turn or ends its turn there.\nAt Higher Levels. When you cast this spell using a\nspell slot of 6th level or higher, the damage increases by\nldlO for each slot level above 5th.","fromHandbook":true},{"n":"Mass Cure Wounds","l":5,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"60 feet","components":"V, S","duration":"Instantaneous","concentration":false,"description":"A wave of healing energywashes out from a point of\nyour choice within range. Choose up to six creatures\nin a 30-foot-radius sphere centered on that point. Each\ntarget regains hit points equal to 3d8 + your spellcasting\nability modifier. This spell has no effect on undead\nor constructs.\nAt Higher Levels. When you cast this spell using a\nspell slot of 6th level or higher, the healing increases by\nld8 for each slot level above 5th.","fromHandbook":true},{"n":"Planar Binding","l":5,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 hour","range":"60 feet","components":"V, S, M (ajewel worth at least 1,000 gp,","duration":"24 hours","concentration":false,"description":"With this spell, you attempt to bind a celestial, an\nelemental, a fey, or a fiend to your service. The creature\nmust be within range for the entire casting of the spell.\n(Typically, the creature is first summoned into the center\nof an inverted magic circle in order to keep it trapped\nwhile this spell is cast.) At the completion of the casting,\nthe target must make a Charisma saving throw. On a\nfailed save, it is bound to serve you for the duration. If\nthe creature was summoned or created by another spell,\nthat spell's duration is extended to match the duration\nof this spell.\nA bound creature must follow your instructions to the\nbest of its ability. You might command the creature to\naccompany you on an adventure, to guard a location, or\nto deliver a message. The creature obeys the letter of\nyour instructions, but if the creature is hostile to you, it\nstrives to twist your words to achieve its own objectives.\nIf the creature carries out your instructions completely\nbefore the spell ends, it travels to you to report this fact\nifyou are on the same plane of existence. If you are on a\ndifferent plane of existence, it returns to the place where\nyou bound it and remains there until the spell ends.\nAt Higher Levels. When you cast this spell using a\nspell slot of a higher level, the duration increases to 10\ndays with a 6th-level slot, to 30 days with a 7th-level slot,\nto 180 days with an 8th-level slot, and to a year and a\nday with a 9th-level spell slot.","fromHandbook":true},{"n":"Reincarnate","l":5,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 hour","range":"Touch","components":"V, S, M (rare oils and unguents worth at","duration":"Instantaneous","concentration":false,"description":"You touch a dead humanoid or a piece of a dead\nhumanoid. Provided that the creature has been dead no\nlonger than 10 days, the spell forms a new adult body\nfor it and then calls the soul to enter that body. If the\ntarget's soul isn't free or willing to do so, the spell fails.\nThe magic fashions a new body for the creature\nto inhabit, which likely causes the creature's race to\nchange. The DM rolls a dlOO and consults the following\ntable to determine what form the creature takes when\nrestored to life, or the DM chooses a form.\ndlOO Race\n01-04 Dragonborn\n05-1 3 Dwarf, hill\n14-21 Dwarf, mountain\n22-25 Elf, dark\n26-34 Elf, high\n35-42 Elf, wood\n43-46 G nome, forest\n47-52 Gnome, rock\n53-56 Half-elf\n57-60 Half-ore\n61 -68 Halfling, lightfoot\n69-76 Halfling, stout\n77-96 Human\n97-00 Tiefling\nThe reincarnated creature recalls its former life\nand experiences. It retains the capabilities it had in its\noriginal form, except it exchanges its original race for\nthe new one and changes its racial traits accordingly.","fromHandbook":true},{"n":"Scrying","l":5,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"10 minutes","range":"Self","components":"V, S, M (a focus worth at least 1 ,000 gp,","duration":"Concentration, up to 10 minutes","concentration":true,"description":"You can see and hear a particular creature you choose\nthat is on the same plane of existence as you. The target\nmust make a Wisdom saving throw, which is modified\nby how well you know the target and the sort of physical\nconnection you have to it. If a target knows you're\ncasting this spell, it can fail the saving throw voluntarily\nif it wants to be observed.\nKnowledge Save Modifier\nSecondhand (you have heard ofthe target) +5\nFirsthand (you have met the target) +O\nFamiliar (you know the target well) -5\nConnection Save Modifier\nLikeness or picture - 2\nPossession or garment -4\nBody part, lock ofhair, bit of nail, or the like -10\nOn a successful save, the target isn't affected, and you\ncan't use this spell against it again for 24 hours.\nOn a failed save, the spell creates an invisible sensor\nwithin 10 feet ofthe target. You can see and hear through\nthe sensor as ifyou were there. The sensor moves with\nthe target, remaining within 10 feet of it for the duration.\nA creature that can see invisible objects sees the sensor\nas a luminous orb about the size ofyour fist.\nInstead oftargeting a creature, you can choose a\nlocation you have seen before as the target of this spell.\nWhen you do, the sensorappears at that location and\ndoesn't move.\n\n2 71-","fromHandbook":true},{"n":"Tree Stride","l":5,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Self","components":"V, S","duration":"Concentration, up to 1 minute","concentration":true,"description":"You gain the ability to enter a tree and move from inside\nit to inside another tree of the same kind within 500\nfeet. Both trees must be living and at least the same size\nas you. You must use 5 feet of movement to enter a tree.\nYou instantly know the location of all other trees of the\nsame kind within 500 feet and, as part of the move used\nto enter the tree, can either pass into one of those trees\nor step out of the tree you're in. You appear in a spot of\nyour choice within 5 feet of the destination tree, using\nanother 5 feet ofmovement. Ifyou have no movement\nleft, you appear within 5 feet of the tree you entered.\nYou can use this transportation ability once per round\nfor the duration. You must end each turn outside a tree.","fromHandbook":true},{"n":"Wall of Stone","l":5,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"120 feet","components":"V, S, M (a small block of granite)","duration":"Concentration, up to 10 minutes","concentration":true,"description":"A nonmagical wall of solid stone springs into existence\nat a point you choose within range. The wall is 6 inches\nthick and is composed of ten 10-foot-by-10-foot panels.\nEach panel must be contiguous with at least one other\npanel. Alternatively, you can create 10-foot-by-20-foot\npanels that are only 3 inches thick.\nIf the wall cuts through a creature's space when it\nappears, the creature is pushed to one side of the wall\n(your choice). If a creature would be surrounded on all\nsides by the wall (or the wall and another solid surface),\nthat creature can make a Dexterity saving throw. On a\nsuccess, it can use its reaction to move up to its speed so\nthat it is no longer enclosed by the wall.\nThe wall can have any shape you desire, though it\ncan't occupy the same space as a creature or object.\nThe wall doesn't need to be vertical or rest on any firm\nfoundation. It must, however, merge with and be solidly\nsupported by existing stone. Thus, you can use this spell\nto bridge a chasm or create a ramp.\nIfyou create a span greater than 20 feet in length, you\nmust halve the size of each panel to create supports.\nYou can crudely shape the wall to create crenellations,\nbattlements, and so on.\nThe wall is an object made of stone that can be\ndamaged and thus breached. Each panel has AC 15 and\n30 hit points per inch of thickness. Reducing a panel\nto 0 hit points destroys it and might cause connected\npanels to collapse at the DM's discretion.\nIfyou maintain your concentration on this spell for\nits whole duration, the wall becomes permanent and\ncan't be dispelled. Otherwise, the wall disappears when\nthe spell ends.","fromHandbook":true},{"n":"Conjure Fey","l":6,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 minute","range":"90 feet","components":"V, S","duration":"Concentration, up to 1 hour","concentration":true,"description":"You summon a fey creature of challenge rating 6 or\nlower, or a fey spirit that takes the form of a beast of\nchallenge rating 6 or lower. It appears in an unoccupied\nspace that you can see within range. The fey creature\ndisappears when it drops to 0 hit points or when\nthe spell ends.\nThe fey creature is friendly to you and your\ncompanions for the duration. Roll initiative for the\ncreature, which has its own turns. It obeys any verbal\ncommands that you issue to it (no action required\nby you), as long as they don't violate its alignment. If\nyou don't issue any commands to the fey creature, it\ndefends itselffrom hostile creatures but otherwise\ntakes no actions.\nIfyour concentration is broken, the fey creature\ndoesn't disappear. Instead, you lose control of the\nfey creature, it becomes hostile toward you and your\ncompanions, and it might attack. An uncontrolled fey\ncreature can't be dismissed by you, and it disappears 1\nhour after you summoned it.\nThe DM has the fey creature's statistics.\nAt Higher Levels. When you cast this spell using\na spell slot of 7th level or higher, the challenge rating\nincreases by 1 for each slot level above 6th.","fromHandbook":true},{"n":"Find the Path","l":6,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 minute","range":"Self","components":"V, S, M (a set of divinatory tools-such","duration":"Concentration, up to 1 day","concentration":true,"description":"This spell allows you to find the shortest, most direct\nphysical route to a specific fixed location that you are\nfamiliar with on the same plane of existence. If you\n\nname a destination on another plane of existence, a\ndestination that moves (such as a mobile fortress), or a\ndestination that isn't specific (such as \"a green dragon's\nlair\"), the spell fails.\nFor the duration, as long as you are on the same plane\nof existence as the destination, you know howfar it is\nand in what direction it lies. While you are traveling\nthere, whenever you are presented with a choice of\npaths along the way, you automatically determine which\npath is the shortest and most direct route (but not\nnecessarily the safest route) to the destination.","fromHandbook":true},{"n":"Heal","l":6,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"60 feet","components":"V, S","duration":"Instantaneous","concentration":false,"description":"Choose a creature that you can see within range. A\nsurge of positive energy washes through the creature,\ncausing it to regain 70 hit points. This spell also ends\nblindness, deafness, and any diseases affecting the\ntarget. This spell has no effect on constructs or undead.\nAt HigherLevels. When you cast this spell using a\nspell slot of 7th level or higher, the amount of healing\nincreases by 10 for each slot level above 6th.","fromHandbook":true},{"n":"Heroes Feast","l":6,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"10 minutes","range":"30 feet","components":"V, S , M (a gem-encrusted bowl worth at","duration":"Instantaneous","concentration":false,"description":"You bring forth a great feast, including magnificent\nfood and drink. The feast takes 1 hour to consume and\ndisappears at the end of that time, and the beneficial\neffects don't set in until this hour is over. Up to twelve\ncreatures can partake of the feast.\nA creature that partakes of the feast gains several\nbenefits. The creature is cured of all diseases and\npoison, becomes immune to poison and being\nfrightened, and makes all Wisdom saving throws with\nadvantage. Its hit point maximum also increases by\n2dl0, and it gains the same number of hit points. These\nbenefits last for 24 hours.","fromHandbook":true},{"n":"Move Earth","l":6,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"120 feet","components":"V, S, M (an iron blade and a small bag","duration":"Concentration, up to 2 hours","concentration":true,"description":"Choose an area of terrain no larger than 40 feet on a\nside within range. You can reshape dirt, sand, or clay\nin the area in any manner you choose for the duration.\nYou can raise or lower the area's elevation, create or fill\nin a trench, erect or flatten a wall, or form a pillar. The\nextent of any such changes can't exceed half the area's\nlargest dimension. So, ifyou affect a 40-foot square,\nyou can create a pillar up to 20 feet high, raise or lower\nthe square's elevation by up to 20 feet, dig a trench up\nto 20 feet deep, and so on. It takes 10 minutes for these\nchanges to complete.\nAt the end ofevery 10 minutes you spend\nconcentrating on the spell, you can choose a new area of\nterrain to affect.\nBecause the terrain's transformation occurs slowly,\ncreatures in the area can't usually be trapped or injured\nby the ground's movement.\nThis spell can't manipulate natural stone or\nstone construction. Rocks and structures shift to\naccommodate the new terrain. If the way you shape\nthe terrain would make a structure unstable, it\nmight collapse.\nSimilarly, this spell doesn't directly affect plant\ngrowth. The moved earth carries anyplants along with it.","fromHandbook":true},{"n":"Sunbeam","l":6,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Self (60-foot line)","components":"V, S, M (a magnifying glass)","duration":"Concentration, up to 1 minute","concentration":true,"description":"A beam of brilliant light flashes out from your hand\nin a 5-foot-wide, 60-foot-long line. Each creature in\nthe line must make a Constitution saving throw. On a\nfailed save, a creature takes 6d8 radiant damage and\nis blinded until your next turn. On a successful save,\nit takes half as much damage and isn't blinded by this\nspell. Undead and oozes have disadvantage on this\nsaving throw.\nYou can create a new line of radiance as your action\non any turn until the spell ends.\nFor the duration, a mote of brilliant radiance shines in\nyour hand. It sheds bright light in a 30-foot radius and\ndim light for an additional 30 feet. This light is sunlight.","fromHandbook":true},{"n":"Transport via Plants","l":6,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"10 feet","components":"V, S","duration":"1 round","concentration":false,"description":"This spell creates a magical link between a Large or\nlarger inanimate plant within range and another plant,\nat any distance, on the same plane ofexistence. You\nmust have seen or touched the destination plant at least\nonce before. For the duration, any creature can step into\nthe target plant and exit from the destination plant by\nusing 5 feet of movement.","fromHandbook":true},{"n":"Wall of Thorns","l":6,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"120 feet","components":"V, S, M (a handful of thorns)","duration":"Concentration, up to 10 minutes","concentration":true,"description":"You create a wall of tough, pliable, tangled brush\nbristling with needle-sharp thorns. The wall appears\nwithin range on a solid surface and lasts for the\nduration. You choose to make the wall up to 60 feet\nlong, 10 feet high, and 5 feet thick or a circle that has\na 20-foot diameter and is up to 20 feet high and 5 feet\nthick. The wall blocks line of sight.\nWhen the wall appears, each creature within its area\nmust make a Dexterity saving throw. On a failed save,\na creature takes 7d8 piercing damage, or half as much\ndamage on a successful save.\nA creature can move through the wall, albeit slowly\nand painfully. For every 1 foot a creature moves\nthrough the wall, it must spend 4 feet of movement.\nFurthermore, the first time a creature enters the wall\non a turn or ends its turn there, the creature must\nmake a Dexterity saving throw. It takes 7d8 slashing\ndamage on a failed save, or half as much damage on a\nsuccessful one.\nAt Higher Levels. When you cast this spell using a\nspell slot of 7th level or higher, both types of damage\nincrease by ld8 for each slot level above 6th.","fromHandbook":true},{"n":"Wind Walk","l":6,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 minute","range":"30 feet","components":"V, S, M (fire and holy water)","duration":"8 hours","concentration":false,"description":"You and up to ten willing creatures you can see\nwithin range assume a gaseous form for the duration,\nappearing as wisps of cloud. While in this cloud form,\na creature has a flying speed of 300 feet and has\nresistance to damage from nonmagical weapons. The\nonly actions a creature can take in this form are the\nDash action or to revert to its normal form. Reverting\ntakes 1 minute, during which time a creature is\nincapacitated and can't move. Until the spell ends, a\ncreature can revert to cloud form, which also requires\nthe 1-minute transformation.\nIf a creature is in cloud form and flying when the effect\nends, the creature descends 60 feet per round for 1\nminute until it lands, which it does safely. If it can't land\nafter 1 minute, the creature falls the remaining distance.","fromHandbook":true},{"n":"Fire Storm","l":7,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"150 feet","components":"V, S","duration":"Instantaneous","concentration":false,"description":"A storm made up of sheets of roaring flame appears\nin a location you choose within range. The area of the\nstorm consists of up to ten 10-foot cubes, which you can\narrange as you wish. Each cube must have at least one\nface adjacent to the face of another cube. Each creature\nin the area must make a Dexterity saving throw. It\ntakes 7d10 fire damage on a failed save, or half as much\ndamage on a successful one.\nThe fire damages objects in the area and ignites\nflammable objects that aren't being worn or carried.\nIfyou choose, plant life in the area is unaffected\nby this spell.","fromHandbook":true},{"n":"Mirage Arcane","l":7,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"10 minutes","range":"Sight","components":"V, S","duration":"10 days","concentration":false,"description":"You make terrain in an area up to 1 mile square\nlook, sound, smell, and even feel like some other sort\nof terrain. The terrain's general shape remains the\nsame, however. Open fields or a road could be made to\nresemble a swamp, hill, crevasse, or some other difficult\nor impassable terrain. A pond can be made to seem like\na grassy meadow, a precipice like a gentle slope, or a\nrock-strewn gully like a wide and smooth road.\nSimilarly, you can alter the appearance of structures,\nor add them where none are present. The spell doesn't\ndisguise, conceal, or add creatures.\nThe illusion includes audible, visual, tactile, and\nolfactory elements, so it can turn clear ground into\ndifficult terrain (or vice versa) or otherwise impede\nmovement through the area. Any piece of the illusory\nterrain (such as a rock or stick) that is removed from the\nspell's area disappears immediately.\nCreatures with truesight can see through the illusion\nto the terrain's true form; however, all other elements\nof the illusion remain, so while the creature is aware of\nPA RT ; ,PEllS\nthe illusion's presence, the creature can still physically\ninteract with the illusion.","fromHandbook":true},{"n":"Plane Shift","l":7,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Touch","components":"V, S, M (a forked, metal rod worth at least","duration":"Instantaneous","concentration":false,"description":"You and up to eight willing creatures who link hands in\na circle are transported to a different plane of existence.\nYou can specify a target destination in general terms,\nsuch as the City of Brass on the Elemental Plane of\nFire or the palace of Dispater on the second level of the\nNine Hells, and you appear in or near that destination.\nIfyou are trying to reach the City of Brass, for example,\nyou might arrive in its Street of Steel, before its Gate of\nAshes, or looking at the city from across the Sea of Fire,\nat the DM's discretion.\nAlternatively, ifyou know the sigil sequence of a\nteleportation circle on another plane of existence, this\nspell can take you to that circle. If the teleportation\ncircle is too small to hold all the creatures you\ntransported, they appear in the closest unoccupied\nspaces next to the circle.\nYou can use this spell to banish an unwilling creature\nto another plane. Choose a creature within your reach\nand make a melee spell attack against it. On a hit, the\ncreature must make a Charisma saving throw. If the\ncreature fails this save, it is transported to a random\nlocation on the plane of existence you specify. A creature\nso transported must find its own way back to your\ncurrent plane of existence.","fromHandbook":true},{"n":"Regenerate","l":7,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 minute","range":"Touch","components":"V, S, M (a prayer wheel and holy water)","duration":"1 hour","concentration":false,"description":"You touch a creature and stimulate its natural healing\nability. The target regains 4d8 + 15 hit points. For the\nduration of the spell, the target regains 1 hit point at the\nstart of each of its turns (10 hit points each minute).\nThe target's severed body members (fingers, legs,\ntails, and so on), ifany, are restored after 2 minutes.\nIfyou have the severed part and hold it to the stump,\nthe spell instantaneously causes the limb to knit\nto the stump.","fromHandbook":true},{"n":"Reverse Gravity","l":7,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"100 feet","components":"V, S, M (a lodestone and iron filings)","duration":"Concentration, up to 1 minute","concentration":true,"description":"This spell reverses gravity in a SO-foot-radius, 100-\nfoot high cylinder centered on a pointwithin range. All\ncreatures and objects that aren't somehow anchored to\nthe ground in the area fall upward and reach the top of\nthe area whenyou cast this spell. A creature can make a\nDexterity saving throw to grab onto a fixed object it can\nreach, thus avoiding the fall.\nIf some solid object (such as a ceiling) is encountered\nin this fall, falling objects and creatures strike it just as\nthey would during a normal downward fall. If an object\nor creature reaches the top of the area without striking\nanything, it remains there, oscillating slightly, for\nthe duration.\nAt the end of the duration, affected objects and\ncreatures fall back down.","fromHandbook":true},{"n":"Animal Shapes","l":8,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"30 feet","components":"V, S","duration":"Concentration, up to 24 hours","concentration":true,"description":"Your magic turns others into beasts. Choose any\nnumber of willing creatures that you can see within\nrange. You transform each target into the form of a\nLarge or smaller beast with a challenge rating of 4 or\nlower. On subsequent turns, you can use your action to\ntransform affected creatures into new forms.\nThe transformation lasts for the duration for each\ntarget, or until the target drops to 0 hit points or dies.\nYou can choose a different form for each target. A\ntarget's game statistics are replaced by the statistics of\nthe chosen beast, though the target retains its alignment\nand Intelligence, Wisdom, and Charisma scores. The\ntarget assumes the hit points of its new form, and when\nit reverts to its normal form, it returns to the number\nof hit points it had before it transformed. If it reverts as\na result of dropping to 0 hit points, any excess damage\ncarries over to its normal form. As long as the excess\ndamage doesn't reduce the creature's normal form to 0\nhit points, it isn't knocked unconscious. The creature is\nlimited in the actions it can perform by the nature of its\nnew form, and it can't speak or cast spells.\nThe target's gear melds into the new form. The target\ncan't activate, wield, or otherwise benefit from any of\nits equipment.","fromHandbook":true},{"n":"Antipathy Sympathy","l":8,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 hour","range":"60 feet","components":"V, S, M (either a lump of alum soaked in","duration":"10 days","concentration":false,"description":"This spell attracts or repels creatures ofyour choice.\nYou target something within range, either a Huge or\nsmaller object or creature or an area that is no larger\nthan a 200-foot cube. Then specify a kind of intelligent\ncreature, such as red dragons, goblins, or vampires.\nYou invest the target with an aura that either attracts or\nrepels the specified creatures for the duration. Choose\nantipathy or sympathy as the aura's effect.\nAntipathy. The enchantment causes creatures of the\nkind you designated to feel an intense urge to leave the\narea and avoid the target. When such a creature can\nsee the target or comes within 60 feet of it, the creature\nmust succeed on a Wisdom saving throw or become\nfrightened. The creature remains frightened while it can\nsee the target or is within 60 feet of it. While frightened\nby the target, the creature must use its movement to\n\nmove to the nearest safe spot from which it can't see\nthe target. If the creature moves more than 60 feet from\nthe target and can't see it, the creature is no longer\nfrightened, but the creature becomes frightened again if\nit regains sight of the target or moves within 60 feet of it.\nSympathy. The enchantment causes the specified\ncreatures to feel an intense urge to approach the target\nwhile within 60 feet of it or able to see it. When such a\ncreature can see the target or comes within 60 feet of it,\nthe creature must succeed on a Wisdom saving throw or\nuse its movement on each of its turns to enter the area\nor move within reach of the target. When the creature\nhas done so, it can't willingly move awayfrom the target.\nIf the target damages or otherwise harms an affected\ncreature, the affected creature can make a Wisdom\nsaving throw to end the effect, as described below.\nEnding the Eff\nect. If an affected creature ends its\nturn while not within 60 feet of the target or able to see\nit, the creature makes a Wisdom saving throw. On a\nsuccessful save, the creature is no longer affected by\nthe target and recognizes the feeling of repugnance or\nattraction as magical. In addition, a creature affected by\nthe spell is allowed another Wisdom saving throw every\n24 hours while the spell persists.\nA creature that successfully saves against this effect\nis immune to it for 1 minute, after which time it can be\naffected again.","fromHandbook":true},{"n":"Control Weather","l":8,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"10 minutes","range":"Self (5-mile radius)","components":"V, S, M (burning incense and bits of earth","duration":"Concentration, up to 8 hours","concentration":true,"description":"You take control of the weather within 5 miles ofyou\nfor the duration. You must be outdoors to cast this spell.\nMoving to a place whereyou don't have a clear path to\nthe sky ends the spell early.\nWhen you cast the spell, you change the current\nweather conditions, which are determined by the DM\nbased on the climate and season. You can change\nprecipitation, temperature, and wind. It takes ld4 x 10\nminutes for the new conditions to take effect. Once they\ndo so, you can change the conditions again. When the\nspell ends, the weather gradually returns to normal.\nWhen you change the weather conditions, find a\ncurrent condition on the following tables and change its\nstage by one, up or down. When changing the wind, you\ncan change its direction.\n\nPR E C I P I TATI O N\nStage Condition\nl Clear\n2 Light clouds\n3 Overcast or ground fog\n4 Rain, hail, or snow\n5 Torrential rain, driving hail, or blizzard\nTE M PERAT U R E\nStage Condition\nl Unbearable heat\n2 Hot\n3 Warm\n4 Cool\n5 Cold\n6 Arctic cold","fromHandbook":true},{"n":"Earthquake","l":8,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"500 feet","components":"V, S, M (a pinch of dirt, a piece of rock,","duration":"Concentration, up to 1 minute","concentration":true,"description":"You create a seismic disturbance at a point on the\nground that you can see within range. For the duration,\nan intense tremor rips through the ground in a\n100-foot-radius circle centered on that point and shakes\ncreatures and structures in contact with the ground\nin that area.\nThe ground in the area becomes difficult terrain.\nEach creature on the ground that is concentrating must\nmake a Constitution saving throw. On a failed save, the\ncreature's concentration is broken.\nWhen you cast this spell and at the end of each turn\nyou spend concentrating on it, each creature on the\nground in the area must make a Dexterity saving throw.\nOn a failed save, the creature is knocked prone.\nThis spell can have additional effects depending on\nthe terrain in the area, as determined by the DM.\nFissures. Fissures open throughout the spell's area at\nthe start ofyour next turn after you cast the spell. A total\nof ld6 such fissures open in locations chosen by the DM.\nEach is ldlO x 10 feet deep, 10 feet wide, and extends\nfrom one edge of the spell's area to the opposite side.\nA creature standing on a spot where a fissure opens\nmust succeed on a Dexterity saving throw or fall in. A\ncreature that successfully saves moves with the fissure's\nedge as it opens.\nA fissure that opens beneath a structure causes it to\nautomatically collapse (see below).\nStructures. The tremor deals 50 bludgeoning damage\nto any structure in contact with the ground in the area\nwhen you cast the spell and at the start of each ofyour\nturns until the spell ends. If a structure drops to 0 hit\npoints, it collapses and potentially damages nearby\ncreatures. A creature within half the distance of a\nstructure's height must make a Dexterity saving throw.\nOn a failed save, the creature takes 5d6 bludgeoning\ndamage, is knocked prone, and is buried in the rubble,\nrequiring a DC 20 Strength (Athletics) check as an\naction to escape. The DM can adjust the DC higher\nor lower, depending on the nature of the rubble. On\na successful save, the creature takes half as much\ndamage and doesn't fall prone or become buried.","fromHandbook":true},{"n":"Feeblemind","l":8,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"150 feet","components":"V, S, M (a handful of clay, crystal, glass,","duration":"Instantaneous","concentration":false,"description":"You blast the mind of a creature that you can see within\nrange, attempting to shatter its intellect and personality.\nThe target takes 4d6 psychic damage and must make an\nIntelligence saving throw.\nOn a failed save, the creature's Intelligence and\nCharisma scores become 1 . The creature can't cast\nspells, activate magic items, understand language, or\n\ncommunicate in any intelligible way. The creature can,\nhowever, identify its friends, follow them, and even\nprotect them.\nAt the end of every 30 days, the creature can repeat\nits saving throw against this spell. If it succeeds on its\nsaving throw, the spell ends.\nThe spell can also be ended bygreaterrestoration,\nheal, or wish.","fromHandbook":true},{"n":"Sunburst","l":8,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"150 feet","components":"V, S, M (fire and a piece of sunstone)","duration":"Instantaneous","concentration":false,"description":"Brilliant sunlight flashes in a 60-foot radius centered\non a point you choose within range. Each creature in\nthat light must make a Constitution saving throw. On a\nfailed save, a creature takes 12d6 radiant damage and is\nblinded for 1 minute. On a successful save, it takes half\nas much damage and isn't blinded by this spell. Undead\nand oozes have disadvantage on this saving throw.\nA creature blinded by this spell makes another\nConstitution saving throw at the end of each of its turns.\nOn a successful save, it is no longer blinded.\nThis spell dispels any darkness in its area that was\ncreated by a spell.","fromHandbook":true},{"n":"Tsunami","l":8,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 minute","range":"Sight","components":"V, S","duration":"Concentration, up to 6 rounds","concentration":true,"description":"A wall ofwater springs into existence at a point you\nchoose within range. You can make the wall up to 300\nfeet long, 300 feet high, and 50 feet thick. The wall lasts\nfor the duration.\nWhen the wall appears, each creature within its area\nmust make a Strength saving throw. On a failed save,\na creature takes 6d10 bludgeoning damage, or half as\nmuch damage on a successful save.\nAt the start of each ofyour turns after the wall\nappears, the wall, along with any creatures in it, moves\n50 feet away from you. Any Huge or smaller creature\ninside the wall or whose space the wall enters when\nit moves must succeed on a Strength saving throw or\ntake 5d10 bludgeoning damage. A creature can take\nthis damage only once per round. At the end of the turn,\nthe wall's height is reduced by 50 feet, and the damage\ncreatures take from the spell on subsequent rounds is\nreduced by ldlO. When the wall reaches 0 feet in height,\nthe spell ends.\nA creature caught in the wall can move by swimming.\nBecause of the force of the wave, though, the creature\nmust make a successful Strength (Athletics) check\nagainst your spell save DC in order to move at all. If it\nfails the check, it can't move. A creature that moves out\nof the area falls to the ground.","fromHandbook":true},{"n":"Foresight","l":9,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 minute","range":"Touch","components":"V, S, M (a hummingbird feather)","duration":"8 hours","concentration":false,"description":"You touch a willing creature and bestow a limited ability\nto see into the immediate future. For the duration, the\ntarget can't be surprised and has advantage on attack\nrolls, ability checks, and saving throws. Additionally,\nother creatures have disadvantage on attack rolls\nagainst the target for the duration.\nThis spell immediately ends ifyou cast it again before\nits duration ends.","fromHandbook":true},{"n":"Shapechange","l":9,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Self","components":"V, S, M (ajade circlet worth at least 1 ,500","duration":"Concentration, up to 1 hour","concentration":true,"description":"You assume the form of a different creature for the\nduration. The new form can be of any creature with\na challenge rating equal to your level or lower. The\n\ncreature can't be a construct or an undead, and you\nmust have seen the sort of creature at least once. You\ntransform into an average example of that creature, one\nwithout any class levels or the Spellcasting trait.\nYour game statistics are replaced by the statistics\nof the chosen creature, though you retain your\nalignment and Intelligence, Wisdom, and Charisma\nscores. You also retain all ofyour skill and saving\nthrow proficiencies, in addition to gaining those of the\ncreature. If the creature has the same proficiency as you\nand the bonus listed in its statistics is higher than yours,\nuse the creature's bonus in place ofyours. You can't use\nany legendary actions or lair actions of the new form.\nYou assume the hit points and Hit Dice of the new\nform. When you revert to your normal form, you\nreturn to the number of hit points you had before you\ntransformed. If you revert as a result of dropping to\n0 hit points, any excess damage carries over to your\nnormal form. As long as the excess damage doesn't\nreduce your normal form to 0 hit points, you aren't\nknocked unconscious.\nYou retain the benefit of any features from your class,\nrace, or other source and can use them, provided that\nyour new form is physically capable of doing so. You\ncan't use any special senses you have (for example,\ndarkvision) unless your new form also has that sense.\nYou can only speak if the creature can normally speak.\nWhen you transform, you choose whether your\nequipment falls to the ground, merges into the new\nform, or is worn by it. Worn equipment functions as\nnormal. The DM determines whether it is practical for\nthe new form to wear a piece of equipment, based on\nthe creature's shape and size. Your equipment doesn't\nchange shape or size to match the new form, and any\nequipment that the new form can't wear must either fall\nto the ground or merge into your new form. Equipment\nthat merges has no effect in that state.\nDuring this spell's duration, you can use your action to\nassume a different form following the same restrictions\nand rules for the original form, with one exception: if\nyour new form has more hit points than your current\none, your hit points remain at their current value.","fromHandbook":true},{"n":"Storm of Vengeance","l":9,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 action","range":"Sight","components":"V, S","duration":"Concentration, up to 1 minute","concentration":true,"description":"A churning storm cloud forms, centered on a point you\ncan see and spreading to a radius of 360 feet. Lightning\nflashes in the area, thunder booms, and strong winds\nroar. Each creature under the cloud (no more than 5,000\nfeet beneath the cloud) when it appears must make a\nConstitution saving throw. On a failed save, a creature\ntakes 2d6 thunder damage and becomes deafened\nfor 5 minutes.\nEach round you maintain concentration on this spell,\nthe storm produces different effects on your turn.\nRound2. Acidic rain falls from the cloud.\nEach creature and object under the cloud takes\nld6 acid damage.\nRound3. You call six bolts of lightning from the\ncloud to strike six creatures or objects ofyour choice\nbeneath the cloud. A given creature or object can't be\nstruckby more than one bolt. A struck creature must\nmake a Dexterity saving throw. The creature takes\n10d6 lightning damage on a failed save, or half as much\ndamage on a successful one.\nRound 4. Hailstones rain down from the\ncloud. Each creature under the cloud takes 2d6\nbludgeoning damage.\nRound 5-10. Gusts and freezing rain assail the\narea under the cloud. The area becomes difficult\nterrain and is heavily obscured. Each creature there\ntakes ld6 cold damage. Ranged weapon attacks in\nthe area are impossible. The wind and rain count as\na severe distraction for the purposes of maintaining\nconcentration on spells. Finally, gusts of strong wind\n(ranging from 20 to 50 miles per hour) automatically\ndisperse fog, mists, and similar phenomena in the area,\nwhether mundane or magical.","fromHandbook":true},{"n":"True Resurrection","l":9,"school":"PHB 2014","classes":["Druida"],"source":"PHB 2014","casting_time":"1 hour","range":"Touch","components":"V, S, M (a sprinkle of holy water and","duration":"Instantaneous","concentration":false,"description":"You touch a creature that has been dead for no longer\nthan 200 years and that died for any reason except\nold age. If the creature's soul is free and willing, the\ncreature is restored to life with all its hit points.\nThis spell closes all wounds, neutralizes any poison,\ncures all diseases, and lifts any curses affecting the\ncreature when it died. The spell replaces damaged or\nmissing organs and limbs. If the creature was undead, it\nis restored to its non-undead form.\nThe spell can even provide a new body if the original\nno longer exists, in which case you must speak the\ncreature's name. The creature then appears in an\nunoccupied spaceyou choose within 10 feet ofyou.","fromHandbook":true},{"n":"Absorb Elements","l":1,"school":"Abjuración","classes":["Druida","Explorador","Hechicero","Mago"],"summary":"Reacción; mitiga un tipo de daño elemental y fortalece el siguiente golpe.","source":"XGE (resumen existente)","range":"Personal","concentration":false,"damage":"+1d6 de tipo elemental absorbido al siguiente golpe cuerpo a cuerpo","description":"Reacción; mitiga un tipo de daño elemental y fortalece el siguiente golpe.","summaryOnly":true},{"n":"Summon Beast","l":2,"school":"Conjuración","classes":["Druida","Explorador"],"summary":"Concentración; invoca un espíritu bestial con bloque específico.","source":"TCE (resumen existente)","range":"90 pies","concentration":true,"damage":"Depende del bloque del espíritu invocado","description":"Concentración; invoca un espíritu bestial con bloque específico.","summaryOnly":true},{"n":"Summon Fey","l":3,"school":"Conjuración","classes":["Druida","Explorador","Brujo","Mago"],"summary":"Concentración; invoca espíritu feérico con opciones de humor.","source":"TCE (resumen existente)","range":"90 pies","concentration":true,"damage":"Depende del bloque del espíritu invocado","description":"Concentración; invoca espíritu feérico con opciones de humor.","summaryOnly":true},{"n":"Summon Elemental","l":4,"school":"Conjuración","classes":["Druida","Explorador","Mago"],"summary":"Concentración; invoca espíritu elemental.","source":"TCE (resumen existente)","range":"90 pies","concentration":true,"damage":"Depende del bloque del espíritu invocado","description":"Concentración; invoca espíritu elemental.","summaryOnly":true},{"n":"Healing Spirit","l":2,"school":"Conjuración","classes":["Druida","Explorador"],"summary":"Concentración; espíritu que proporciona curaciones limitadas.","source":"XGE (resumen existente)","range":"60 pies","concentration":true,"damage":"No inflige daño; cura 1d6 por uso (según versión)","description":"Concentración; espíritu que proporciona curaciones limitadas.","summaryOnly":true},{"n":"Flame Arrows","l":3,"school":"Transmutación","classes":["Druida","Explorador","Hechicero","Mago"],"summary":"Concentración; añade daño de fuego a proyectiles.","source":"XGE (resumen existente)","range":"Toque","concentration":true,"damage":"+1d6 fuego por proyectil afectado","description":"Concentración; añade daño de fuego a proyectiles.","summaryOnly":true},{"n":"Tidal Wave","l":3,"school":"Conjuración","classes":["Druida","Hechicero","Mago"],"summary":"Oleada de agua que causa daño y puede derribar.","source":"XGE (resumen existente)","range":"120 pies","concentration":false,"damage":"4d8 contundente","description":"Oleada de agua que causa daño y puede derribar.","summaryOnly":true},{"n":"Erupting Earth","l":3,"school":"Transmutación","classes":["Druida","Hechicero","Mago"],"summary":"Explosión de tierra que causa daño y deja terreno difícil.","source":"XGE (resumen existente)","range":"120 pies","concentration":false,"damage":"3d12 contundente (más al potenciar)","description":"Explosión de tierra que causa daño y deja terreno difícil.","summaryOnly":true},{"n":"Watery Sphere","l":4,"school":"Conjuración","classes":["Druida","Hechicero","Mago"],"summary":"Concentración; esfera acuática que atrapa y transporta criaturas.","source":"XGE (resumen existente)","range":"90 pies","concentration":true,"damage":"No inflige daño directo","description":"Concentración; esfera acuática que atrapa y transporta criaturas.","summaryOnly":true},{"n":"Whirlwind","l":7,"school":"Evocación","classes":["Druida","Mago"],"summary":"Concentración; torbellino que puede atrapar criaturas.","source":"XGE (resumen existente)","range":"300 pies","concentration":true,"damage":"10d6 contundente por exposición (según condiciones)","description":"Concentración; torbellino que puede atrapar criaturas.","summaryOnly":true}];
